import { useCallback, useRef } from "react";
import * as THREE from "three";

/*
 * Cosmic space background using Three.js (npm-installed).
 * - Deep space gradient background (#020205)
 * - Twinkling star field (400 stars of varying sizes)
 * - Nebula-like floating particle clusters (purple/pink/cyan)
 * - Slow camera drift + mouse parallax
 * - Full-screen canvas behind content; clicks pass through
 */

export default function CosmicBackground() {
  const cleanupRef = useRef(null);
  const rafRef = useRef(null);

  const handleRef = useCallback((canvasEl) => {
    // Run previous cleanup if React is detaching the ref (passing null)
    if (cleanupRef.current) {
      cleanupRef.current();
      cleanupRef.current = null;
    }

    if (!canvasEl) return;

    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x020205, 0.002);

    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    camera.position.z = 10;

    const renderer = new THREE.WebGLRenderer({
      canvas: canvasEl,
      antialias: true,
      alpha: true,
      powerPreference: "high-performance",
    });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.setClearColor(0x020205, 1);

    // ---- Star field ----
    const starCount = 400;
    const starGeometry = new THREE.BufferGeometry();
    const starPositions = new Float32Array(starCount * 3);
    const starSizes = new Float32Array(starCount);

    for (let i = 0; i < starCount * 3; i += 3) {
      starPositions[i] = (Math.random() - 0.5) * 200;
      starPositions[i + 1] = (Math.random() - 0.5) * 200;
      starPositions[i + 2] = (Math.random() - 0.5) * 100;
      starSizes[i / 3] = Math.random() * 1.5 + 0.5;
    }

    starGeometry.setAttribute(
      "position",
      new THREE.BufferAttribute(starPositions, 3)
    );

    const starMaterial = new THREE.PointsMaterial({
      color: 0xffffff,
      size: 0.8,
      transparent: true,
      opacity: 0.9,
      sizeAttenuation: true,
    });

    const stars = new THREE.Points(starGeometry, starMaterial);
    scene.add(stars);

    // ---- Nebula particle clusters ----
    const clusterCount = 3;
    const clusters = [];
    const nebulaColors = [0xbc13fe, 0xff0055, 0x00d2ff];

    for (let c = 0; c < clusterCount; c++) {
      const count = 200;
      const geometry = new THREE.BufferGeometry();
      const positions = new Float32Array(count * 3);
      const velocities = new Float32Array(count * 3);
      const opacities = new Float32Array(count);

      const cx = (Math.random() - 0.5) * 80;
      const cy = (Math.random() - 0.5) * 80;
      const cz = (Math.random() - 0.5) * 60;

      for (let i = 0; i < count * 3; i += 3) {
        positions[i] = cx + (Math.random() - 0.5) * 15;
        positions[i + 1] = cy + (Math.random() - 0.5) * 15;
        positions[i + 2] = cz + (Math.random() - 0.5) * 15;
        velocities[i] = (Math.random() - 0.5) * 0.01;
        velocities[i + 1] = (Math.random() - 0.5) * 0.01;
        velocities[i + 2] = (Math.random() - 0.5) * 0.005;
        opacities[i / 3] = Math.random() * 0.6 + 0.2;
      }

      geometry.setAttribute(
        "position",
        new THREE.BufferAttribute(positions, 3)
      );
      geometry.setAttribute("opacity", new THREE.BufferAttribute(opacities, 1));

      const material = new THREE.PointsMaterial({
        color: nebulaColors[c],
        size: 0.6,
        transparent: true,
        opacity: 0.5,
        sizeAttenuation: true,
      });

      const cluster = new THREE.Points(geometry, material);
      cluster.userData = { velocities };
      scene.add(cluster);
      clusters.push(cluster);
    }

    // ---- Mouse parallax ----
    const mouse = new THREE.Vector2(0, 0);
    const target = new THREE.Vector3(0, 0, 0);

    function onMouseMove(event) {
      mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
      mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
    }

    function onWindowResize() {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    }

    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("resize", onWindowResize);

    let lastTime = 0;

    function animate(time = 0) {
      const dt = time - lastTime;
      lastTime = time;

      target.x = mouse.x * 10;
      target.y = mouse.y * 8;
      camera.position.x += (target.x - camera.position.x) * 0.005;
      camera.position.y += (target.y - camera.position.y) * 0.005;
      camera.lookAt(scene.position);

      starMaterial.opacity = 0.7 + Math.sin(time * 0.001) * 0.2;

      clusters.forEach((cluster) => {
        const positions = cluster.geometry.attributes.position.array;
        const velocities = cluster.userData.velocities;
        const count = positions.length / 3;

        for (let i = 0; i < count * 3; i += 3) {
          positions[i] += velocities[i];
          positions[i + 1] += velocities[i + 1];
          positions[i + 2] += velocities[i + 2];

          const cx2 = cluster.position.x || 0;
          const cy2 = cluster.position.y || 0;
          const cz2 = cluster.position.z || 0;
          if (Math.abs(positions[i] - cx2) > 20) velocities[i] *= -1;
          if (Math.abs(positions[i + 1] - cy2) > 20) velocities[i + 1] *= -1;
          if (Math.abs(positions[i + 2] - cz2) > 20) velocities[i + 2] *= -1;
        }

        cluster.geometry.attributes.position.needsUpdate = true;
        cluster.rotation.y += 0.0002;
        cluster.rotation.x += 0.0001;
      });

      renderer.render(scene, camera);
      rafRef.current = requestAnimationFrame(animate);
    }

    animate();

    cleanupRef.current = () => {
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("resize", onWindowResize);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      renderer.dispose();
      renderer.forceContextLoss();
    };
  }, []);

  return (
    <canvas ref={handleRef} className="cosmic-canvas" aria-hidden="true" />
  );
}
